test.describe('Product Detail Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://www.saucedemo.com');
    await page.fill('[data-test="username"]', 'standard_user');
    await page.fill('[data-test="password"]', 'secret_sauce');
    await page.click('[data-test="login-button"]');
  });

  test('should navigate to product detail page', async ({ page }) => {
    await page.getByRole('link', { name: 'Sauce Labs Backpack' }).click();
    await page.waitForURL(/.*inventory-item.html/);
    expect(await page.url()).toContain('inventory-item.html');
  });

  test('should return to catalogue from product detail page', async ({ page }) => {
    await page.getByRole('link', { name: 'Sauce Labs Backpack' }).click();
    await page.getByTestId('back-to-products').click();
    await page.waitForURL(/.*inventory.html/);
    expect(await page.getByText('Products')).toBeVisible();
  });
});
